def word_frequencies(text):
    """Count case-insensitive, whitespace-separated words in ``text``."""
    counts = {}
    for word in text.split():
        if word.lower() in counts:
            counts[word.lower()] += 1
        else:
            counts[word.lower()] = 1
    return counts

