def normalize_whitespace(text):
    """Collapse runs of whitespace to one space and strip both ends."""
    out = ""
    pending_space = False
    for ch in text:
        if ch in " \t\n\r":
            pending_space = bool(out)
        else:
            if pending_space:
                out += " "
                pending_space = False
            out += ch
    return out

